def run(data):
    arch = str(data.get('ARCH_321', ''))
    m31 = [2, 3, 5, 7, 11, 12, 14, 18, 20, 24, 25, 31, 32, 34, 40, 44, 46, 50, 51, 57, 63, 65, 66, 72, 73, 77, 79, 85, 86, 90, 91]
    m30 = m31[:-1]

    def clean(w):
        return ''.join(ch for ch in w.lower() if ch.isalpha())

    words = [clean(w) for w in arch.split()]
    words = [w for w in words if w]
    letters = ''.join(words)
    out = []
    for unit_name, units in (('w', words), ('l', list(letters))):
        pages = [units[i:i + 91] for i in range(0, len(units), 91)]
        for mask in (m31, m30):
            sel = []
            for pg in pages:
                sel.append([pg[p - 1] for p in mask if p - 1 < len(pg)])
            comp_sel = []
            for pg in pages:
                ms = set(mask)
                comp_sel.append([pg[i] for i in range(len(pg)) if (i + 1) not in ms])
            sep = ' ' if unit_name == 'w' else ''
            for k, x in enumerate(sel):
                out.append(sep.join(x))
            if unit_name == 'l':
                for k, x in enumerate(comp_sel):
                    out.append(sep.join(x))
            # same grid cell across pages
            for p in mask:
                col = [pg[p - 1] for pg in pages if p - 1 < len(pg)]
                out.append(sep.join(col))
            # all pages concatenated, masked positions only
            out.append(sep.join(y for x in sel for y in x))
            # mask applied to consecutive 91-blocks via 7x13 transposition (column order of the grid)
            colsel = []
            for pg in pages:
                if len(pg) == 91:
                    cols = [pg[j + 13 * i] for j in range(13) for i in range(7)]
                    colsel.append([cols[p - 1] for p in mask])
            for x in colsel:
                out.append(sep.join(x))
    # prime scaffold applied to letters of the whole text: primes of the letter index
    res = []
    got = set()
    for x in out:
        if x and len(x) <= 200 and x not in got:
            got.add(x)
            res.append(x)
    return res[:2000]

def run(data):
    dbbi = ''.join(ch for ch in str(data.get('DBBI', '')).lower() if 'a' <= ch <= 'i')
    faed = ''.join(ch for ch in str(data.get('FAED', '')).lower() if 'a' <= ch <= 'i')
    if len(dbbi) != 91 or len(faed) != 570:
        return []
    url = 'gsmg.io/theseedisplanted'
    n = 14
    seen = set()
    sp = []
    r = c = 0
    dr, dc = 1, 0
    for _ in range(n * n):
        sp.append((r + 1, c + 1))
        seen.add((r, c))
        nr, nc = r + dr, c + dc
        if not (0 <= nr < n and 0 <= nc < n) or (nr, nc) in seen:
            dr, dc = -dc, dr
            nr, nc = r + dr, c + dc
        r, c = nr, nc
    bits = ''.join(format(ord(ch), '08b') for ch in url)
    grid = {}
    for i in range(192):
        grid[sp[i]] = (bits[i], url[i // 8])

    def digrams(s):
        return [(ord(s[i]) - 96, ord(s[i + 1]) - 96) for i in range(0, len(s) - 1, 2)]

    def tobytes(bs):
        return [int(bs[i:i + 8], 2) for i in range(0, len(bs) - 7, 8)]

    out = []
    streams = [('faed', faed), ('dbbi', dbbi), ('dbbi+faed', dbbi + faed), ('faed+dbbi', faed + dbbi), ('faed-odd', faed[1:])]
    for nm, s in streams:
        dg = digrams(s)
        for off in (0, 3):
            for swap in (0, 1):
                bs = ''
                tx = ''
                for (x, y) in dg:
                    a, b = (y, x) if swap else (x, y)
                    cell = (a + off, b + off)
                    bs += grid[cell][0] if cell in grid else '0'
                    tx += grid[cell][1] if cell in grid else '?'
                for inv in (0, 1):
                    q = ''.join('1' if ch == '0' else '0' for ch in bs) if inv else bs
                    by = tobytes(q)
                    hx = ''.join(format(v, '02x') for v in by)
                    if len(hx) >= 64:
                        out.append(hx[:64])
                        out.append(hx[-64:])
                    if len(hx) <= 200:
                        out.append(hx)
                    out.append(''.join(chr(v) for v in by if 32 <= v < 127))
                    out.append(''.join(chr(v & 127) for v in by if 32 <= (v & 127) < 127))
                    if len(q) >= 256:
                        # every second bit / first bit of each pair, as 64-hex
                        for step in (2, 3):
                            if len(q) >= 256 * step:
                                z = q[::step][:256]
                                out.append(format(int(z, 2), '064x'))
                out.append(tx[:200])
                out.append(tx[::-1][:200])
    res = []
    got = set()
    for x in out:
        if x and len(x) <= 200 and x not in got:
            got.add(x)
            res.append(x)
    return res
